#[test]
    fn text_changed_round_trips_over_the_shared_ring() {
        use pathland_core::component_type;

        let mut m = Memory::new(MemoryLayout::default());

        {
            let mut h = m.host();
            h.send_event(&Event::TextChanged {
                target: 7,
                value: "hello".into(),
            })
            .unwrap();
        }

        let mut g = m.guest();
        assert_eq!(
            g.drain_events(),
            vec![Event::TextChanged {
                target: 7,
                value: "hello".into()
            }]
        );
        assert!(g.drain_events().is_empty());

        // The event arena cursor advanced past the entry.
        let cursor = pathland_core::memory::header::get_u32(
            &m.mem[..pathland_core::memory::HEADER_SIZE],
            pathland_core::memory::OFF_EVENT_ARENA_CURSOR,
        );
        assert_eq!(cursor, 4 + 5, "4-byte length prefix + 5 bytes of text");

        // Sanity: tree frames and the event arena coexist.
        {
            let mut g2 = m.guest();
            g2.begin_frame();
            g2.create_node(1, component_type::VSTACK).unwrap();
            g2.end_frame();
        }
        {
            let mut h2 = m.host();
            assert_eq!(h2.frames().len(), 1);
        }
    }

    #[test]
    fn reset_recycles_the_event_arena() {
        let mut m = Memory::new(MemoryLayout::default());

        {
            let mut h = m.host();
            h.send_event(&Event::TextChanged {
                target: 1,
                value: "aaa".into(),
            })
            .unwrap();
        }
        {
            let mut g = m.guest();
            assert_eq!(g.drain_events().len(), 1);
        }

        // A guest META::RESET frame resets the host's event arena cursor.
        {
            let mut g = m.guest();
            g.begin_frame();
            g.reset();
            g.end_frame();
        }
        {
            let mut h = m.host();
            assert_eq!(h.frames().len(), 1);
        }
        let cursor = pathland_core::memory::header::get_u32(
            &m.mem[..pathland_core::memory::HEADER_SIZE],
            pathland_core::memory::OFF_EVENT_ARENA_CURSOR,
        );
        assert_eq!(cursor, 0, "event arena cursor resets on META::RESET");

        // The host can write fresh text into the recycled arena.
        {
            let mut h = m.host();
            h.send_event(&Event::TextChanged {
                target: 2,
                value: "bb".into(),
            })
            .unwrap();
        }
        {
            let mut g = m.guest();
            assert_eq!(
                g.drain_events(),
                vec![Event::TextChanged {
                    target: 2,
                    value: "bb".into()
                }]
            );
        }
    }
