package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.WritableSignal;

import java.util.List;

/**
 * A selection control (SwiftUI {@code Picker}). The options are the child nodes, in
 * display order; {@code SELECTION} is the selected child index. Changes flow back as
 * {@code VALUE_CHANGED} (the new index) into the binding.
 */
public final class Picker implements View {

    private final PickerStyle style;
    private final WritableSignal<Integer> selection;
    private final List<View> options;

    public Picker(PickerStyle style, WritableSignal<Integer> selection, View... options) {
        this.style = style;
        this.selection = selection;
        this.options = List.of(options);
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.PICKER);
        node.properties.put(Properties.PICKER_STYLE, (float) style.wire());
        node.properties.put(Properties.SELECTION, selection.get());
        node.propertyBindings.put(Properties.SELECTION, selection);
        node.valueInput = v -> selection.set(Math.round(v));
        for (View option : options) {
            node.children.add(option.render(env));
        }
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.WritableSignal;

import java.util.List;

/**
 * A contextual action trigger and popover container (SwiftUI {@code Menu}). The first
 * child is the custom trigger; the rest are action items ({@code Button}/{@code Toggle}/
 * nested {@code Menu}). When a {@code selection} binding is provided, choosing an item
 * reports its index as {@code VALUE_CHANGED}.
 */
public final class Menu implements View {

    private final List<View> children;
    private final WritableSignal<Integer> selection;

    public Menu(View trigger, View... actions) {
        this(trigger, null, actions);
    }

    public Menu(View trigger, WritableSignal<Integer> selection, View... actions) {
        List<View> all = new java.util.ArrayList<>(1 + actions.length);
        all.add(trigger);
        all.addAll(List.of(actions));
        this.children = List.copyOf(all);
        this.selection = selection;
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.MENU);
        for (View child : children) {
            node.children.add(child.render(env));
        }
        if (selection != null) {
            node.valueInput = v -> selection.set(Math.round(v));
        }
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.WritableSignal;

/**
 * A native system color picker (SwiftUI {@code ColorPicker}). The selected color binds
 * to a {@link WritableSignal<Color>}; changes flow back as {@code VALUE_CHANGED} carrying
 * the packed {@code 0xAARRGGBB} color reinterpreted as an f32 bit pattern.
 */
public final class ColorPicker implements View {

    private final WritableSignal<Color> binding;

    public ColorPicker(WritableSignal<Color> binding) {
        this.binding = binding;
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.COLOR_PICKER);
        node.properties.put(Properties.COLOR_VALUE, binding.get());
        node.propertyBindings.put(Properties.COLOR_VALUE, binding);
        node.valueInput = v -> binding.set(new Color(Float.floatToRawIntBits(v)));
        return node;
    }
}

