                        View.toggle(ToggleStyle.CHECKBOX, notify.get(), notify.signal(), "Notify me"),
                        View.toggle(ToggleStyle.BUTTON, bold.get(), bold.signal(), "Bold toggle"),
                        View.text(summary).padding(4)
                ).padding(4)
        );
    }
}

