      new Opcode(CATEGORY.STYLE, STYLE.SET_DATE, 0, 1, 20487, 43200000),
    ], new Uint8Array());

    const tree = new RetainedTree();
    tree.applyFrame(decodeFrame(bytes));

    expect(tree.node(1)?.date()).toEqual({ days: 20487, millis: 43200000 });
  });
});

